#!/usr/bin/env python3
from __future__ import annotations

import base64
import json
import zlib
from pathlib import Path

# A52_TOUCHGRASS_CRITICAL_FLIGHT_RECORDER_V1 payload. Materializes the audited
# recorder patcher, checker, decoder, build harness and design note.
PAYLOAD = r""""""

def main() -> int:
    files = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'))
    for name, content in files.items():
        path = Path(name)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding='utf-8')
        if path.suffix in {'.py', '.sh'}:
            path.chmod(0o755)
        print(f'materialized {name}')
    return 0

if __name__ == '__main__':
    raise SystemExit(main())
